/* CSS */
.text { color: green; }

<!-- HTML -->
<p class="text" style="color: orange;">Hello</p>

a:hover {
  color: orange;
}
a {
  color: teal;
}

button[disabled] {
  background-color: gray;
}
button {
  background-color: blue;
}

.box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid black;
}

.box {
  box-sizing: content-box;
  width: 200px;
  padding: 10px;
  border: 2px solid black;
}

button:where(.primary, .accent) {
  color: white;
}
button {
  color: black;
}

button:is(.primary, .accent) {
  color: white;
}
button {
  color: black;
}
